import csv, json, math, unittest
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/"data/geocodificacao/fonte_complementar"; SRC=ROOT.parent
def rows(name):
    with (OUT/name).open(encoding="utf-8-sig",newline="") as f:return list(csv.DictReader(f))

class Sprint06Tests(unittest.TestCase):
 @classmethod
 def setUpClass(c):
  c.sample=rows("amostra_10.csv"); c.result=rows("resultado_piloto.csv"); c.comp=rows("comparacao_fontes.csv"); c.query=rows("consultas_piloto.csv"); c.qa=rows("qa_piloto.csv"); c.stats=json.loads((OUT/"estatisticas_piloto.json").read_text(encoding="utf-8")); c.man=json.loads((OUT/"manifesto_geo_complementar_001.json").read_text(encoding="utf-8")); c.r05=rows("../recuperacao_geo001/resultado_recuperacao.csv"); c.geo=json.loads((ROOT/"data/pontos_classe_a.geojson").read_text(encoding="utf-8"))
 def test_01_baseline(self):self.assertTrue((ROOT.parent/"safeflow-map-sprint05-baseline/BASELINE_SPRINT05.json").exists())
 def test_02_universe_42(self):self.assertEqual(self.man["universo_total"],42)
 def test_03_sample_10(self):self.assertEqual(len(self.sample),10)
 def test_04_unique_sample(self):self.assertEqual(len({x["ID_ENDERECO"] for x in self.sample}),10)
 def test_05_deterministic_order(self):self.assertEqual([x["MUNICIPIO"] for x in self.sample],sorted(x["MUNICIPIO"] for x in self.sample))
 def test_06_only_b(self):self.assertTrue({x["ID_ENDERECO"] for x in self.sample}<={x["ID_ENDERECO"] for x in self.r05 if x["CLASSIFICACAO_APOS_RECUPERACAO"]=="B_MANTIDO"})
 def test_07_no_geo002(self):self.assertTrue(self.man["nenhum_geo002"])
 def test_08_no_not_found(self):self.assertTrue({x["ID_ENDERECO"] for x in self.sample}.isdisjoint({x["ID_ENDERECO"] for x in self.r05 if x["CLASSIFICACAO_APOS_RECUPERACAO"]=="NAO_ENCONTRADO"}))
 def test_09_no_review(self):self.assertTrue({x["ID_ENDERECO"] for x in self.sample}.isdisjoint({x["ID_ENDERECO"] for x in self.r05 if x["CLASSIFICACAO_APOS_RECUPERACAO"]=="REVISAO_MANUAL"}))
 def test_10_queries_10(self):self.assertEqual(len(self.query),10)
 def test_11_structured_query(self):self.assertTrue(all("street=" in x["CONSULTA_ENVIADA"] and "housenumber=" in x["CONSULTA_ENVIADA"] for x in self.query))
 def test_12_original_responses(self):self.assertEqual(len(list((OUT/"respostas_provedor").glob("END_*.json"))),10)
 def test_13_original_number(self):self.assertTrue(all(x["NUMERO_ORIGINAL"] for x in self.result))
 def test_14_complement_number_field(self):self.assertTrue(all("NUMERO_FONTE_COMPLEMENTAR" in x for x in self.result))
 def test_15_number_comparison(self):self.assertTrue(all(x["NUMERO_COMPATIVEL"] in {"true","false"} for x in self.result))
 def test_16_city_recorded(self):self.assertTrue(all("MUNICIPIO_COMPLEMENTAR" in x for x in self.result))
 def test_17_state_recorded(self):self.assertTrue(all("UF_COMPLEMENTAR" in x for x in self.result))
 def test_18_cep_compared(self):self.assertTrue(all(x["CEP_COMPATIVEL"] in {"true","false"} for x in self.result))
 def test_19_precision_field(self):self.assertTrue(all(x["PRECISAO_DECLARADA"] for x in self.result))
 def test_20_coordinate_flag(self):self.assertTrue(all(x["COORDENADAS_VALIDAS"] in {"true","false"} for x in self.result))
 def test_21_haversine_nonnegative(self):self.assertTrue(all(float(x["DISTANCIA_COMPLEMENTAR_NOMINATIM_METROS"])>=0 for x in self.comp if x["DISTANCIA_COMPLEMENTAR_NOMINATIM_METROS"]))
 def test_22_conflict_flag(self):self.assertTrue(all(x["CONFLITO"] in {"true","false"} for x in self.comp))
 def test_23_missing_number_not_confirmed(self):self.assertTrue(all(x["NUMERO_COMPATIVEL"]=="false" for x in self.result if not x["NUMERO_FONTE_COMPLEMENTAR"]))
 def test_24_no_rooftop_auto_publish(self):self.assertTrue(all(x["PUBLICAR"]=="false" for x in self.result))
 def test_25_candidate_requires_qa(self):self.assertTrue(all(x["QA"]!="" for x in self.result if x["RESULTADO_PILOTO"]=="CANDIDATO_A_RECUPERADO"))
 def test_26_qa_registered(self):self.assertEqual({x["ID_ENDERECO"] for x in self.qa},{x["ID_ENDERECO"] for x in self.result if x["RESULTADO_PILOTO"]=="CANDIDATO_A_RECUPERADO"})
 def test_27_only_a_publish(self):self.assertTrue(all(x["PUBLICAR"]=="false" or x["RESULTADO_APOS_QA"]=="A_RECUPERADO" for x in self.result))
 def test_28_18_preserved(self):self.assertEqual(len(self.geo["features"]),18)
 def test_29_total_reconciled(self):self.assertEqual(len(self.geo["features"]),self.stats["publicados_depois"])
 def test_30_geojson(self):self.assertEqual(self.geo["type"],"FeatureCollection")
 def test_31_filters(self):self.assertTrue((ROOT/"js/filter-core.js").exists())
 def test_32_sede(self):self.assertEqual(len(json.loads((ROOT/"data/sede.geojson").read_text(encoding="utf-8"))["features"]),1)
 def test_33_radius(self):self.assertIn("radius",(ROOT/"js/filter-core.js").read_text(encoding="utf-8").lower())
 def test_34_cache_terms(self):self.assertEqual(json.loads((OUT/"decisao_fonte.json").read_text(encoding="utf-8"))["cache_permitido_para_piloto"],True)
 def test_35_no_credentials(self):self.assertFalse(self.man["credencial_usada"])
 def test_36_no_cost(self):self.assertEqual(self.stats["custo_monetario"],0)
 def test_37_no_routes(self):self.assertFalse(any(x["geometry"]["type"]=="LineString" for x in self.geo["features"]))
 def test_38_no_sequence(self):self.assertNotIn("sequencia_visita",json.dumps(self.geo).lower())
 def test_39_no_optimization(self):self.assertNotIn("otimizacao",json.dumps(self.geo).lower())
 def test_40_hashes(self):self.assertEqual(len(self.man["hashes_fontes_sha256"]),4)
 def test_41_rollback(self):self.assertTrue((ROOT.parent/"safeflow-map-sprint05-baseline").exists())
 def test_42_no_expansion(self):self.assertFalse(self.stats["expansao_32_executada"])
 def test_43_provider(self):self.assertTrue(all(x["PROVEDOR"]=="Photon/komoot" for x in self.result))
 def test_44_provenance(self):self.assertTrue(all(x["ORIGEM_VALIDACAO"]=="SPRINT06_FONTE_COMPLEMENTAR" for x in self.result))
 def test_45_result_count(self):self.assertEqual(len(self.result),10)
 def test_46_cache_has_attempt_history(self):self.assertEqual(len(json.loads((OUT/"cache_photon.json").read_text(encoding="utf-8"))),20)
 def test_47_same_ten_after_retry(self):self.assertEqual({x["ID_ENDERECO"] for x in self.result},{x["ID_ENDERECO"] for x in self.sample})
 def test_48_metric_number(self):self.assertEqual(self.stats["taxa_confirmacao_numero"],0.0)
 def test_49_metric_safe(self):self.assertEqual(self.stats["taxa_recuperacao_segura"],0.0)
 def test_50_no_paid_api(self):self.assertTrue(self.man["nenhum_custo"])

if __name__=="__main__":unittest.main()
